INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) SELECT 'ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-3-invu', 'Partners INVU', concepto, enseñanza, ejemplo, NULL, NULL, NULL, orden FROM (VALUES ('El Cliente Satisfecho como el Mejor Referidor', 'El cliente satisfecho de INVU es el mejor referidor porque tiene experiencia directa con el sistema y puede dar testimonio de su valor. Su recomendación tiene un peso enorme porque viene de alguien que ya confía en INVU. El programa de referidos convierte a los clientes satisfechos en una extensión del equipo de ventas, amplificando el alcance comercial de INVU sin costo adicional.', 'Un cliente de INVU con 2 locales recomienda el sistema a un colega restaurador. Le dice: "Nos cambió la vida: incluimos facturación electrónica nativa sin pagar extra a Nubefact, centralizamos el inventario de los 2 locales, y vemos reportes en tiempo real desde el celular. Además, el soporte es 24/7 en Perú." El colega confía en la recomendación y agenda una reunión con INVU. El cliente satisfecho cobra S/1,000 por la referencia.', 1),
('El Manejo de la Objeción "No Necesito Cambiar"', 'El referidor debe manejar la objeción del potencial cliente que dice "no necesito cambiar mi sistema". La respuesta es validar su postura, pero luego preguntar: "¿Tienes control de inventario en tiempo real? ¿Tu facturación electrónica está integrada o pagas aparte? ¿Puedes centralizar tus sedes y ver reportes consolidados?" Si el cliente responde que no a estas preguntas, el referidor puede mostrar que INVU es una mejora, no solo un cambio.', 'Un referidor le dice a un restaurador: "Entiendo. Pero ¿tienes control de inventario en tiempo real? ¿Tu facturación electrónica está integrada o pagas aparte? ¿Puedes centralizar tus sedes y ver reportes consolidados? INVU hace todo eso en un solo sistema. Te recomiendo que al menos los conozcas, no pierdes nada." El restaurador, que paga Nubefact aparte y no centraliza su inventario, se queda pensando y acepta la reunión.', 2),
('El Manejo de la Objeción "Es Caro"', 'El referidor debe manejar la objeción del potencial cliente que dice "es caro". La respuesta es validar su preocupación, pero luego mostrar que cuando se suman los costos de facturación electrónica aparte, soporte, y sistemas separados, INVU termina siendo más barato. Además, el control de inventario y la reducción de mermas pagan la inversión.', 'Un referidor le dice a un restaurador: "Yo pensé lo mismo, pero cuando sumas lo que pagas por facturación electrónica aparte, por soporte, y por sistemas separados, termina siendo más barato. Además, el control que te da en inventario y la reducción de mermas pagan la inversión. Vale la pena conocerlos." El restaurador, que no había sumado todos los costos, acepta la reunión.', 3),
('El Manejo de la Objeción "Lo Voy a Pensar"', 'El referidor debe manejar la objeción del potencial cliente que dice "lo voy a pensar". La respuesta es validar que es normal, pero ofrecer una demo sin compromiso: "Te propongo que los conozcas en una demo sin compromiso. Después de eso, si lo piensas y decides que no es para ti, no pasa nada." Esto quita presión y permite que el cliente avance en el proceso sin sentirse forzado.', 'Un referidor le dice a un restaurador: "Es normal. Te propongo que los conozcas en una demo sin compromiso. Después de eso, si lo piensas y decides que no es para ti, no pasa nada. ¿Qué te parece?" El restaurador, que se sentía presionado a decidir, se relaja y acepta la demo.', 4),
('El Manejo de la Objeción "Ya Tengo un Amigo que me Recomendó Otro Sistema"', 'El referidor debe manejar la objeción del potencial cliente que dice que ya tiene otra recomendación. La respuesta es no descalificar la otra opción, sino ofrecer una comparación informada: "Perfecto, lo importante es que encuentres la solución que mejor se adapte a ti. Te recomiendo que también conozcas a INVU para comparar. Así tomas una decisión informada."', 'Un referidor le dice a un restaurador: "Perfecto, lo importante es que encuentres la solución que mejor se adapte a ti. Te recomiendo que también conozcas a INVU para comparar. Así tomas una decisión informada. ¿Te parece?" El restaurador, que no quería cerrarse a una sola opción, acepta conocer a INVU.', 5),
('El Manejo de la Objeción del Referidor "No Sé Vender"', 'El referidor que dice "no sé vender" debe recordar que no necesita vender. Solo necesita abrir la puerta y presentar a INVU. INVU es el que cierra. El único trabajo del referidor es conectar y asegurar la reunión. Eso lo puede hacer cualquier persona con contactos en la industria, sin importar su experiencia en ventas.', 'Un contador duda en referir a sus clientes porque cree que necesita saber vender. Pero luego recuerda: "No necesito vender. Solo necesito abrir la puerta y presentar a INVU. INVU es el que cierra. Mi único trabajo es conectar y asegurar la reunión." Con esta mentalidad, contacta a su primer cliente restaurantero y agenda una reunión con INVU.', 6),
('Los Niveles de Dominio del Referidor', 'El referidor pasa por 4 niveles: Básico (identifica oportunidades pero no las registra, pierde comisiones), Medio (presenta y registra, protege su comisión), Alto (construye una red activa, genera flujo constante de comisiones), y Gravedad Cero (se convierte en partner estratégico, con ingresos recurrentes y reconocimiento de INVU). El objetivo es llegar a Gravedad Cero: ser un socio estratégico de INVU con una red amplia y confiable.', 'Básico: Conoce a un restaurador pero no lo refiere formalmente. Pierde la comisión.
Medio: Refiere a un restaurador, registra la oportunidad, y cobra S/1,000.
Alto: Refiere a 5 restauradores al año, todos registrados, ganando S/5,000 anuales.
Gravedad Cero: Tiene una red de 20 contactos en la industria, refiere 10 negocios al año, gana S/10,000+ anuales, e INVU lo reconoce como un aliado de crecimiento.', 7),
('El Registro en CRM – Lo que no se registra, no existe', 'El referidor debe registrar la oportunidad formalmente mediante correo a lizeth@invupos.com con copia a jorge@invupos.com. Sin registro, no hay protección de oportunidad y no hay comisión. El registro es el paso que convierte el esfuerzo del referidor en dinero. No hay atajos.', 'Un referidor asegura una reunión pero se olvida de registrar. El negocio cierra, pero otro referidor había registrado la oportunidad antes. El primero pierde S/1,000. El segundo cobra. El primer referidor aprende la lección: lo que no se registra, no existe.', 8),
('El Bono Especial para Cuentas Consolidadas', 'Para cuentas consolidadas (más de 5 sedes), el referidor no solo cobra S/1,500, sino que tiene posibilidad de bono especial según el tamaño del negocio. Esto reconoce el valor de traer oportunidades de gran escala y incentiva al referidor a enfocarse en cadenas grandes.', 'Un referidor refiere una cadena de 15 restaurantes a INVU. Cobra S/1,500 de comisión base y además recibe un bono especial de S/500 por el tamaño del negocio. Total: S/2,000 por una sola referencia. El referidor se enfoca en buscar más cadenas grandes.', 9),
('El Valor de la Red de Contactos', 'La red de contactos del referidor es su activo más valioso. Cada contacto en la industria gastronómica es una oportunidad potencial de referido. El referidor debe cultivar su red, mantenerse en contacto con los dueños de restaurantes, y estar atento a las oportunidades. Una red amplia y activa es la clave para generar ingresos recurrentes.', 'Un proveedor de insumos tiene una lista de 100 clientes restauranteros. Cada mes, contacta a 5 de ellos para saber cómo va su negocio y si están considerando cambiar de sistema POS. Cuando encuentra a uno que está frustrado con su sistema actual, lo refiere a INVU. Su red de contactos es su máquina de generar ingresos.', 10),
('El Programa de Referidos como Extensión del Equipo de Ventas', 'El programa de referidos convierte a los referidores en una extensión del equipo de ventas de INVU, ampliando su alcance en el mercado peruano sin costo fijo. Los referidores abren puertas que el equipo comercial no podría abrir por sí mismo, aprovechando la confianza y las relaciones personales en la industria. Esto acelera el crecimiento de INVU y genera beneficios para todos.', 'El equipo de ventas de INVU no puede contactar a todos los restaurantes de Lima. Pero 100 referidores, cada uno con 10 contactos en la industria, pueden abrir 1,000 puertas. El programa de referidos multiplica el alcance comercial de INVU, generando más oportunidades de venta y más ingresos para los referidores.', 11),
('El Resultado Esperado – Una Red de Referidores Activos', 'El resultado esperado del programa de referidos es una red de referidores activos que generan un flujo constante de negocios calificados para el equipo comercial de INVU. Los referidores transforman su red de contactos en una fuente de ingresos adicionales, recomiendan a INVU con confianza, registran sus oportunidades correctamente, y cobran sus comisiones sin esfuerzo adicional. El programa de referidos se convierte en un motor de crecimiento para INVU y en una fuente de ingresos para los referidores.', 'Un año después del lanzamiento del programa, INVU tiene 200 referidores activos. Cada referidor refiere un promedio de 2 negocios al año. Son 400 oportunidades calificadas que llegan al equipo comercial. El equipo cierra el 40% de esas oportunidades: 160 nuevos clientes. Los referidores cobran sus comisiones. INVU crece. Todos ganan.


# PÍLDORAS DE CONOCIMIENTO - PROGRAMA PARTNERS INVU POS PERÚ', 12),
('El Partner – Un Socio Estratégico, No un Referidor', 'El Programa Partners es una evolución del programa de referidos. Mientras el referidor cobra una comisión fija (S/500, S/1,000, S/1,500), el Partner cobra el 8% del valor total del primer año del cliente (setup + 12 mensualidades), pagado en tres tramos. El Partner tiene un incentivo para traer clientes más grandes, porque su comisión crece proporcionalmente al tamaño del negocio. El referido es para contactos ocasionales; el Partner es para profesionales que quieren monetizar su red de contactos de manera recurrente.', 'Un contador refiere a un cliente de 1 sede: comisión S/532 (8% de S/6,650). Si el mismo contador refiere una cadena de 10 sedes: comisión S/6,057 (8% de S/75,708). El contador entiende que su red de contactos de clientes grandes vale mucho más. Se convierte en Partner y enfoca sus esfuerzos en las cuentas grandes.', 13),
('El 8% del Valor del Primer Año – Cuanto más Grande, más Ganas', 'La comisión del Partner está directamente ligada al tamaño del negocio que refiere. No es una comisión fija; es el 8% del setup + 12 mensualidades del cliente. Un cliente de 1 sede genera S/532; un cliente de 3 sedes genera S/1,992; un cliente de 10 sedes genera S/6,057; una cuenta estratégica puede generar más de S/10,000. El Partner tiene incentivo para buscar los clientes más grandes y valiosos.', 'Un Partner tiene dos contactos: un restaurante de 1 sede y una cadena de 15 sedes. El primero le daría S/532; el segundo, con comisión preferente del 10%, le daría más de S/13,000. El Partner enfoca su tiempo en la cadena grande porque su esfuerzo se multiplica. La comisión sigue al valor del cliente.', 14),
('Pago en Tres Tramos – Cobro Rápido, Sin Esperas', 'La comisión total se paga en tres tramos: 40% al primer pago del cliente (setup + 1era mensualidad), 30% a los 60 días, 30% a los 90 días. El Partner no tiene que esperar 6 o 12 meses para cobrar su comisión completa. El primer pago llega tan pronto como el cliente firma y paga su primera factura. Esto genera confianza, flujo de caja rápido, y motiva a seguir refiriendo negocios.', 'Un Partner refiere una cadena de 10 sedes. Valor año 1: S/75,708. Comisión 8%: S/6,057. El Partner cobra S/2,423 al primer pago del cliente (40%), S/1,817 a los 60 días (30%), y S/1,817 a los 90 días (30%). En 3 meses, el Partner ha cobrado toda su comisión, sin esperar 12 meses como en otros programas. Esto es un gran diferenciador.', 15)) AS t(concepto, enseñanza, ejemplo, orden);